/**
 * Jira Software Node - Version 1
 * Discriminator: resource=user, operation=delete
 */


interface Credentials {
  jiraSoftwareCloudApi: CredentialReference;
  jiraSoftwareServerApi: CredentialReference;
  jiraSoftwareServerPatApi: CredentialReference;
  jiraSoftwareCloudOAuth2Api: CredentialReference;
  atlassianServiceAccountApi: CredentialReference;
}

/** Get, create and delete a user */
export type JiraV1UserDeleteParams = {
  resource: 'user';
  operation: 'delete';
  jiraVersion?: 'cloud' | 'cloudOAuth2' | 'cloudServiceAccount' | 'server' | 'serverPat' | Expression<string>;
/**
 * The Jira site to use. Can be left empty when the service account has access to exactly one site.
 * @searchListMethod getSites
 * @displayOptions.show { jiraVersion: ["cloudServiceAccount"] }
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url'; value: string; cachedResultName?: string };
/**
 * Account ID of the user to delete
 */
    accountId?: string | Expression<string>;
};

export type JiraV1UserDeleteNode = {
  type: 'n8n-nodes-base.jira';
  version: 1;
  config: NodeConfig<JiraV1UserDeleteParams> & { credentials?: Credentials };
};